import { configFromEnvironment, type HandStackConfig } from '@handstack/config';
import { createDatabaseAdapter, type DatabaseAdapter } from '@handstack/database';
import { Injectable, type OnModuleDestroy, type OnModuleInit } from '@nestjs/common';

@Injectable()
export class DatabaseService implements OnModuleInit, OnModuleDestroy {
  readonly config: HandStackConfig;
  readonly adapter: DatabaseAdapter;
  private initialized = false;

  constructor() {
    this.config = configFromEnvironment(process.env);
    this.adapter = createDatabaseAdapter(this.config);
  }

  async onModuleInit(): Promise<void> {
    await this.adapter.initialize();
    this.initialized = true;
  }

  async onModuleDestroy(): Promise<void> {
    await this.adapter.close();
    this.initialized = false;
  }

  status(): 'up' | 'down' {
    return this.initialized ? 'up' : 'down';
  }
}
import { Injectable } from '@nestjs/common';
import { InMemoryFeatureFlagService } from '@handstack/feature-flags';
import { ValidationError } from '@handstack/shared';
import {
  DistributedJobQueue,
  InMemoryJobQueue,
  RepositoryJobTransport,
  InMemoryOperationStore,
  RepositoryOperationStore,
  type Operation,
  type OperationStore,
  type JobQueueName,
} from '@handstack/jobs';
import { AuditRuntimeService } from '../audit/audit-runtime.service.js';
import { DatabaseService } from '../database/database.service.js';

@Injectable()
export class OperationsRuntimeService {
  readonly flags = new InMemoryFeatureFlagService();
  readonly audit: AuditRuntimeService;
  readonly operations: OperationStore;
  private readonly queues = new Map<
    string,
    InMemoryJobQueue<unknown> | DistributedJobQueue<unknown>
  >();

  constructor(
    audit?: AuditRuntimeService,
    private readonly database?: DatabaseService,
  ) {
    this.audit = audit ?? new AuditRuntimeService();
    this.operations =
      database === undefined
        ? new InMemoryOperationStore()
        : new RepositoryOperationStore(
            (repositoryName) => database.adapter.repository(repositoryName),
          );
  }

  async createOperation(input: {
    organizationId: string;
    type: string;
    idempotencyKey: string;
    result?: unknown;
  }) {
    const idempotencyKey = input.idempotencyKey.trim();
    if (idempotencyKey === '') throw new ValidationError('Idempotency key is required');
    const normalized = { ...input, idempotencyKey };
    const existing = await this.operations.findByIdempotencyKey(
      normalized.organizationId,
      normalized.idempotencyKey,
    );
    if (existing !== undefined) {
      if (existing.type !== normalized.type)
        throw new ValidationError('Operation idempotency key is already bound to another type');
      return existing;
    }
    return this.operations.create(normalized);
  }

  getOperation(organizationId: string, id: string): Promise<Operation | undefined> {
    return this.operations.get(organizationId, id);
  }

  queue(
    name: JobQueueName,
    organizationId = 'default',
  ): InMemoryJobQueue<unknown> | DistributedJobQueue<unknown> {
    const key = `${organizationId}:${name}`;
    let queue = this.queues.get(key);
    if (queue === undefined) {
      const database = this.database;
      queue =
        database === undefined
          ? new InMemoryJobQueue(name)
          : new DistributedJobQueue(
              name,
              new RepositoryJobTransport(
                (repositoryName) => database.adapter.repository(repositoryName),
                organizationId,
              ),
            );
      this.queues.set(key, queue);
    }
    return queue;
  }
}

import type { HandStackConfig } from '@handstack/config';
import { MongoAdapter } from '@handstack/database-mongodb';
import { TypeOrmAdapter } from '@handstack/database-typeorm';
import type {
  Repository,
  RepositoryName,
  TenantEntity,
  TransactionManager,
} from '@handstack/domain';

export interface DatabaseAdapter extends TransactionManager {
  initialize(): Promise<this>;
  repository<T extends TenantEntity>(name: RepositoryName): Repository<T>;
  close(): Promise<void>;
}

function sqliteLocation(url: string): string | undefined {
  if (!url.startsWith('file:'))
    throw new TypeError('SQLite database URL must use the file: scheme');
  const location = url.slice('file:'.length);
  return location === ':memory:' || location.length === 0 ? undefined : location;
}

function mongoDatabaseName(url: string): string {
  const parsed = new URL(url);
  const databaseName = parsed.pathname.replace(/^\//, '');
  if (databaseName.length === 0) throw new TypeError('MongoDB URL must include a database name');
  return databaseName;
}

export function createDatabaseAdapter(config: HandStackConfig): DatabaseAdapter {
  switch (config.database.adapter) {
    case 'sqlite': {
      const location = sqliteLocation(config.database.url);
      return new TypeOrmAdapter(
        location === undefined ? { adapter: 'sqlite' } : { adapter: 'sqlite', location },
      );
    }
    case 'postgresql':
      return new TypeOrmAdapter({ adapter: 'postgresql', url: config.database.url });
    case 'mysql':
      return new TypeOrmAdapter({ adapter: 'mysql', url: config.database.url });
    case 'mariadb':
      return new TypeOrmAdapter({ adapter: 'mariadb', url: config.database.url });
    case 'sqlserver':
      return new TypeOrmAdapter({ adapter: 'sqlserver', url: config.database.url });
    case 'mongodb':
      return new MongoAdapter(config.database.url, mongoDatabaseName(config.database.url));
  }
}

